\section{Introduction}

A finite Markov chain on a state space $S$ is a matrix $P:S\times S\to\RR$ with nonnegative
entries whose rows sum to one. A Kripke frame is a pair $F=(W,R)$ with $R$ a binary relation
on $W$. The two objects differ in what they record: the matrix records \emph{how likely}
each transition is, the frame only \emph{whether} it is possible. This paper carries out the
passage from the first to the second systematically, and shows that in each case the modal
notion and the probabilistic notion are literally the same object.

\subsection{The modal language}
Fix a set $\alpha$ of propositional variables. Modal formulas are generated by
\[
\varphi ::= p \mid \bot \mid \varphi\to\varphi \mid \Box\varphi,\qquad p\in\alpha,
\]
with $\neg\varphi:=\varphi\to\bot$ and $\Dia\varphi:=\neg\Box\neg\varphi$. Given a frame
$F=(W,R)$ and a valuation $V:\alpha\to\mathcal P(W)$, satisfaction is defined as usual, the
modal clause being $w\Vdash\Box\varphi$ iff $v\Vdash\varphi$ for all $v$ with $w\mathrel{R}v$.
A formula is \emph{valid} on $F$ when it is satisfied at every world under every valuation.
We abbreviate the consistency formula $\mathrm{con}:=\neg\Box\bot$ and the L\"ob instance
$L(\varphi):=\Box(\Box\varphi\to\varphi)\to\Box\varphi$.

Write $R^n$ for the $n$-fold relational composite: $R^0$ is equality, and $u\mathrel{R^n}v$
holds iff there is a sequence $u=x_0\mathrel{R}x_1\mathrel{R}\cdots\mathrel{R}x_n=v$, called
an \emph{$n$-path}. Induction on $n$ gives the composition law
\begin{equation}\label{eq:comp}
u\mathrel{R^{n+m}}v \iff \exists z\,\bigl(u\mathrel{R^{n}}z \ \wedge\ z\mathrel{R^{m}}v\bigr),
\end{equation}
which will be read below as iterated box semantics, as matrix multiplication, and as
addition of return times.

\subsection{Modal systems}
A \emph{modal system} over $\alpha$ is a set $T$ of formulas closed under modus ponens and
necessitation. It is \emph{consistent} if $\bot\notin T$; it \emph{proves reflection} if
$\Box\varphi\to\varphi\in T$ for all $\varphi$; and it \emph{proves the L\"ob axiom} if
$L(\varphi)\in T$ for all $\varphi$. The modal form of G\"odel's second incompleteness
theorem states that a consistent L\"obian system does not prove $\mathrm{con}$;
contrapositively, a consistent system proving $\mathrm{con}$ is not L\"obian.

\section{The support functor}

\begin{definition}[Support frame]
For $P:S\times S\to\RR$, the \emph{support frame} $\supp(P)$ has worlds $S$ and
accessibility $u\mathrel{R}v :\iff P(u,v)>0$.
\end{definition}

\begin{definition}
$P$ on a finite $S$ is \emph{row-stochastic} if $P(u,v)\ge 0$ for all $u,v$ and
$\sum_v P(u,v)=1$ for all $u$. The \emph{step powers} are $P^0(u,v)=[u=v]$ and
$P^{n+1}(u,v)=\sum_z P(u,z)P^n(z,v)$.
\end{definition}

\begin{theorem}[Support--power theorem]\label{thm:supp}
Let $P$ have nonnegative entries. For all $n$ and all $u,v$,
\[
P^n(u,v)>0 \iff u\mathrel{R^n}v \text{ in } \supp(P).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Induction on $n$. The base case is the definition of $P^0$ and $R^0$. For the step,
$P^{n+1}(u,v)=\sum_z P(u,z)P^n(z,v)$ is a sum of nonnegative terms, hence positive iff some
term is positive, i.e.\ iff there is $z$ with $P(u,z)>0$ and $P^n(z,v)>0$; by the induction
hypothesis this is the existence of $z$ with $u\mathrel{R}z\mathrel{R^n}v$. The forward
direction is run as a contrapositive: if no such $z$ exists, every summand vanishes.
\end{proof}

\begin{theorem}[Chapman--Kolmogorov]
$P^{n+m}(u,v)=\sum_z P^n(u,z)P^m(z,v)$.
\end{theorem}

\begin{proof}[Proof sketch]
Induction on $n$, expanding $P^{n+1+m}$ and interchanging the two finite summations. This is
the numerical shadow of \eqref{eq:comp}.
\end{proof}

Theorem~\ref{thm:supp} licenses the following dictionary, each line of which is a theorem
proved below.

