\section{Seriality and the impossibility of L\"ob}

\begin{lemma}[Mass forces successors]\label{lem:serial}
If $P$ is row-stochastic then for every $u$ there is $v$ with $P(u,v)>0$; that is,
$\supp(P)$ is serial.
\end{lemma}

\begin{proof}
If all $P(u,v)$ were $\le 0$ then, being also $\ge 0$, they would all vanish and the row sum
would be $0\ne 1$.
\end{proof}

\begin{lemma}[Seriality kills converse well-foundedness]\label{lem:wf}
If $F$ is nonempty and serial, the converse relation is not well-founded.
\end{lemma}

\begin{proof}
Suppose it were. Well-founded induction along the converse relation proves any property
$\Phi$ such that $\Phi$ at all $R$-successors of $w$ implies $\Phi$ at $w$. Take
$\Phi\equiv\bot$: seriality supplies a successor $v$ of $w$, and the induction hypothesis at
$v$ is $\bot$. So $\bot$ holds at every world, contradicting nonemptiness.
\end{proof}

Recall that L\"ob's axiom is valid on $F$ exactly when $R$ is transitive and its converse is
well-founded.

\begin{theorem}[No Markov chain is a L\"ob frame]
Let $S$ be finite and nonempty and let $P$ be row-stochastic. Then $L(p)$ is not valid on
$\supp(P)$ for any variable $p$.
\end{theorem}

\begin{remark}
Finiteness enters only to make sense of the row sum; the underlying incompatibility
(Lemma~\ref{lem:wf}) is purely order-theoretic.
\end{remark}

\begin{theorem}
If $P$ is row-stochastic then $\mathrm{con}$ is valid on $\supp(P)$, since $\mathrm{con}$ is
valid exactly on the serial frames.
\end{theorem}

\begin{definition}
The \emph{modal system of $P$}, denoted $T_P$, is the set of formulas valid on $\supp(P)$.
It is closed under modus ponens and necessitation.
\end{definition}

\begin{theorem}
For $S$ nonempty, $T_P$ is consistent. If moreover $P$ is row-stochastic then
$\mathrm{con}\in T_P$ and $T_P$ is not L\"obian.
\end{theorem}

\begin{proof}
The valuation making every variable false at every world refutes $\bot$, so $T_P$ is
consistent; consistency together with $\mathrm{con}\in T_P$ contradicts L\"obianity.
\end{proof}

\begin{theorem}[Self-soundness equals laziness]\label{thm:lazy}
For finite $S$, $T_P$ proves reflection if and only if $P(w,w)>0$ for every state $w$.
\end{theorem}

\begin{proof}[Proof sketch]
Validity of $\Box\varphi\to\varphi$ at $w$ for all $\varphi$ and all valuations is equivalent
to $w\mathrel{R}w$: if $w$ has no self-loop, take $\varphi=p$ false at $w$ and true
elsewhere; conversely a self-loop makes the implication immediate. Under the support
definition, $w\mathrel{R}w$ is $P(w,w)>0$.
\end{proof}

\begin{corollary}
Every nonempty finite lazy stochastic chain yields a consistent modal system that proves its
own reflection schema, hence its own consistency, and is not L\"obian. The smallest instance
is the one-state chain $P=(1)$, whose support frame is the reflexive point.
\end{corollary}

\begin{theorem}[Tangles are forced]\label{thm:pigeon}
Every nonempty finite row-stochastic chain has a state $w$ and an $n>0$ with
$w\mathrel{R^n}w$.
\end{theorem}

\begin{proof}[Proof sketch]
By Lemma~\ref{lem:serial} choose $g$ with $P(u,g(u))>0$. The orbit $x_0,g(x_0),g^2(x_0),\dots$
is an infinite sequence in a finite set, so $g^i(x_0)=g^j(x_0)$ for some $i<j$; the segment
from $i$ to $j$ is a closed path of length $j-i>0$.
\end{proof}

\section{The soundness spectrum}

\begin{definition}
A world $w$ is \emph{$n$-sound} if for every valuation and every formula $\varphi$,
$w\Vdash\Box^n\varphi$ implies $w\Vdash\varphi$. The \emph{soundness spectrum} is
$\Spec(w)=\{n : w \text{ is } n\text{-sound}\}$.
\end{definition}

\begin{theorem}[Spectrum equals closed walks]\label{thm:spec}
Assuming at least one propositional variable, $w$ is $n$-sound iff $w\mathrel{R^n}w$.
\end{theorem}

\begin{proof}[Proof sketch]
($\Leftarrow$) If $w\mathrel{R^n}w$ then $w\Vdash\Box^n\varphi$ forces $\varphi$ at every
$n$-successor of $w$, in particular at $w$. ($\Rightarrow$) If $\neg(w\mathrel{R^n}w)$, take
the valuation making $p$ true exactly off $w$: then $w\Vdash\Box^n p$ while $w\nVdash p$.
\end{proof}

\begin{corollary}
For $P$ with nonnegative entries, $\Spec(w)=\{n:P^n(w,w)>0\}$: the soundness spectrum of a
state is the support of its return-time distribution.
\end{corollary}

\begin{theorem}[The spectrum is a numerical semigroup]\label{thm:monoid}
$\Spec(w)$ is an additive submonoid of $\NN$.
\end{theorem}

\begin{proof}
$0\in\Spec(w)$ since $R^0$ is equality. Closure under addition is \eqref{eq:comp} with
$u=v=z=w$; probabilistically, $P^{n+m}(w,w)\ge P^n(w,w)P^m(w,w)>0$.
\end{proof}

We call $\Spec(w)$ the \emph{cycle monoid} of $w$.

\begin{example}[The deterministic $n$-cycle]\label{ex:cycle}
Let $C_n$ be the chain on $\ZZ/n$ with $C_n(u,v)=1$ if $v=u+1$ and $0$ otherwise. Induction
gives $u\mathrel{R^k}v$ iff $v=u+k$ in $\ZZ/n$; hence $w$ is $k$-sound iff $n\mid k$, and
$\Spec(w)=n\NN$ for every $w$. The modal invariant ``degree of internal soundness'' coincides
with the probabilistic invariant ``period''. Moreover $C_n$ has positive holding probability
iff $n=1$.
\end{example}

\section{The cofiniteness criterion}

The Chicken McNugget theorem settles cofiniteness when two coprime elements are available,
but a numerical semigroup can have overall $\gcd$ equal to $1$ while no two generators are
coprime, e.g.\ $\langle 6,10,15\rangle$. The right invariant is a common divisor of the whole
monoid.

\begin{definition}
An additive submonoid $S\subseteq\NN$ is \emph{aperiodic} if for every $d\ge 2$ there is
$n\in S$ with $d\nmid n$.
\end{definition}

\begin{lemma}[Box argument]\label{lem:box}
If an additive submonoid $S\subseteq\NN$ contains $y$ and $y+1$, then $n\in S$ for every
$n\ge y^2$.
\end{lemma}

\begin{proof}
If $y=0$ then $1\in S$ and $S=\NN$. Otherwise write $n=qy+r$ with $0\le r<y$. From
$n\ge y^2$ we get $q=\lfloor n/y\rfloor\ge y>r$, so
\[
n = qy+r = (q-r)\,y + r\,(y+1),
\]
a nonnegative combination of two elements of $S$.
\end{proof}

\begin{definition}
For $S$ an additive submonoid of $\NN$ put $D(S)=\{x-y\in\ZZ : x,y\in S\}$. It is a subgroup
of $\ZZ$: closure under addition uses $(x_1-y_1)+(x_2-y_2)=(x_1+x_2)-(y_1+y_2)$, and negation
swaps $x$ and $y$.
\end{definition}

\begin{lemma}[Aperiodicity yields consecutive elements]\label{lem:consec}
If $S$ is aperiodic then $y,y+1\in S$ for some $y$.
\end{lemma}

\begin{proof}
Every subgroup of $\ZZ$ is cyclic, so $D(S)=d\ZZ$ for some $d\ge0$. Each $s\in S$ satisfies
$s=s-0\in D(S)$, so $d\mid s$ for all $s\in S$. If $d=0$ then $S=\{0\}$ and $2$ divides all
of $S$, contradicting aperiodicity; if $d\ge2$ then $d$ divides all of $S$, again a
contradiction. Hence $d=1$, so $1=x-y$ with $x,y\in S$.
\end{proof}

\begin{theorem}[Cofiniteness criterion]\label{thm:cofinite}
An additive submonoid $S\subseteq\NN$ contains all sufficiently large integers if and only if
it is aperiodic. If $y,y+1\in S$ then the conductor may be taken to be $y^2$.
\end{theorem}

\begin{proof}
($\Rightarrow$) If $n\in S$ for all $n\ge N$ and $d\ge2$, then $Nd+1\in S$ and $d\nmid Nd+1$,
since otherwise $d\mid1$. ($\Leftarrow$) Lemma~\ref{lem:consec} followed by
Lemma~\ref{lem:box}.
\end{proof}

\begin{remark}
The proof chooses no generating set, extracts no coprime pair, and computes no Frobenius
number. The two-generator theorem survives only as a source of quantitative information: for
coprime $a,b$ the sharp conductor is $ab-a-b+1$.
\end{remark}

\section{Aperiodicity and primitivity}

\begin{definition}
A world $w$ is \emph{aperiodic} if for every $d\ge2$ there is $k$ with $w\mathrel{R^k}w$ and
$d\nmid k$; equivalently, its cycle monoid is aperiodic. A frame is \emph{irreducible} if
every world reaches every world; a chain is \emph{primitive} if $P^n(u,v)>0$ for all $u,v$
and all sufficiently large $n$.
\end{definition}

\begin{theorem}[Sharp cofiniteness]\label{thm:sharpcof}
For any frame and world, $w\mathrel{R^n}w$ for all sufficiently large $n$ iff $w$ is
aperiodic; equivalently, $\Spec(w)$ is cofinite iff $w$ is aperiodic.
\end{theorem}

\begin{corollary}\label{cor:special}
(i) A self-loop at $w$ makes $w$ aperiodic, since $1\in\Spec(w)$. (ii) Closed walks of
coprime lengths $a,b$ at $w$ make $w$ aperiodic, since a common divisor of all return lengths
divides $\gcd(a,b)=1$.
\end{corollary}

\begin{lemma}[Padding through an aperiodic world]\label{lem:pad}
Let $w$ be aperiodic with cofiniteness threshold $M$, and let $u\mathrel{R^c}w$ and
$w\mathrel{R^{d}}v$. Then $u\mathrel{R^n}v$ for all $n\ge c+d+M$.
\end{lemma}

\begin{proof}
For such $n$ we have $n-c-d\ge M$, so $w\mathrel{R^{n-c-d}}w$; concatenate
$u\to^c w\to^{n-c-d} w\to^{d} v$ using \eqref{eq:comp} twice.
\end{proof}

\begin{theorem}[Perron--Frobenius primitivity, sharp form]\label{thm:prim}
A finite irreducible frame containing one aperiodic world has an $N$ such that
$u\mathrel{R^n}v$ for all $n\ge N$ and all $u,v$.
\end{theorem}

\begin{proof}[Proof sketch]
For each ordered pair $(u,v)$, irreducibility gives $c$ with $u\mathrel{R^c}w$ and $d$ with
$w\mathrel{R^{d}}v$; Lemma~\ref{lem:pad} gives a threshold $N_{u,v}$. Finitely many pairs;
take the maximum.
\end{proof}

\begin{theorem}[Primitivity is aperiodicity]\label{thm:primap}
Let $P$ be a finite irreducible chain with nonnegative entries and $w$ any state. Then $P$ is
primitive iff $w$ is aperiodic.
\end{theorem}

\begin{proof}
($\Leftarrow$) Theorem~\ref{thm:prim} plus Theorem~\ref{thm:supp}. ($\Rightarrow$) If
$P^n(u,v)>0$ for all $n\ge N$ then $w\mathrel{R^n}w$ for all $n\ge N$, so $\Spec(w)$ is
cofinite and Theorem~\ref{thm:sharpcof} applies.
\end{proof}

\begin{corollary}[Aperiodicity is a class property]
In a finite irreducible frame, if one world is aperiodic then all are.
\end{corollary}

\begin{example}[Periodic]
For $n\ge2$ no state of $C_n$ is aperiodic: by Example~\ref{ex:cycle} the return lengths are
exactly the multiples of $n$. So $C_n$ is irreducible but not primitive.
\end{example}

\begin{example}[Aperiodic and loopless]\label{ex:ap}
Let $A$ be the three-state chain with $0\to1$ with probability $1$; $1\to0$ and $1\to2$ each
with probability $1/2$; and $2\to0$ with probability $1$. No state has positive holding
probability, yet state $0$ carries closed walks of lengths $2$ and $3$, which are coprime, so
$0$ is aperiodic by Corollary~\ref{cor:special}(ii); $A$ is irreducible, hence primitive by
Theorem~\ref{thm:primap}. Its soundness spectrum at $0$ is
$\langle2,3\rangle=\{0,2,3,4,\dots\}$, missing only $1$. This case is unreachable by the
self-loop route to primitivity.
\end{example}

\section{Effective exponents}

Write $N=|W|$.

\begin{definition}
A \emph{path function} for an $n$-path from $u$ to $v$ is $f:\NN\to W$ with $f(0)=u$,
$f(n)=v$ and $f(i)\mathrel{R}f(i+1)$ for $i<n$. Path functions and witnesses of
$u\mathrel{R^n}v$ correspond.
\end{definition}

\begin{lemma}[Excision]\label{lem:excise}
If $u\mathrel{R^k}v$ with $k\ge N$, then $u\mathrel{R^{k'}}v$ for some $k'<k$.
\end{lemma}

\begin{proof}[Proof sketch]
The values $f(0),\dots,f(k)$ are $k+1>N$ elements of $W$, so $f(i)=f(j)$ for some $i<j\le k$.
Splice out the loop: $g(m)=f(m)$ for $m\le i$ and $g(m)=f(m+(j-i))$ for $m>i$. Three index
cases show $g$ is a path function of length $k-(j-i)$.
\end{proof}

\begin{theorem}[Diameter principle]\label{thm:diam}
In a finite frame with $N$ worlds, if $v$ is reachable from $u$ at all, then
$u\mathrel{R^{k}}v$ for some $k<N$.
\end{theorem}

\begin{theorem}[Exponent for lazy chains]\label{thm:lazyexp}
If $F$ is finite irreducible and $w\mathrel{R}w$ for every $w$, then $u\mathrel{R^k}v$ for all
$u,v$ and all $k\ge N-1$.
\end{theorem}

\begin{proof}
Theorem~\ref{thm:diam} gives a path of length $\le N-1$; universal self-loops pad it at the
target to any greater length.
\end{proof}

\begin{theorem}[Exponent from a single loop]
If $F$ is finite irreducible and $w_0\mathrel{R}w_0$ for one world $w_0$, then
$u\mathrel{R^k}v$ for all $u,v$ and all $k\ge 2(N-1)$.
\end{theorem}

\begin{proof}
Route through $w_0$: an approach of length $\le N-1$ and an exit of length $\le N-1$
(Theorem~\ref{thm:diam}), padded at $w_0$ by the self-loop.
\end{proof}

Via Theorem~\ref{thm:supp} these say that $P^k$ has all entries positive for $k\ge N-1$
(lazy) and for $k\ge2(N-1)$ (single holding state); correspondingly the soundness spectrum of
every world of a finite irreducible lazy frame contains every $k\ge N-1$.

\begin{theorem}[Sharpness]\label{thm:sharp}
Let $B_N$ be the nearest-neighbour chain on $\{0,\dots,N-1\}$, in which each state may stay
put or move to an adjacent index. Then $B_N$ is irreducible and lazy, and for $N\ge1$ the
matrix $P^k$ has all entries positive if and only if $k\ge N-1$.
\end{theorem}

\begin{proof}[Proof sketch]
The upper bound is Theorem~\ref{thm:lazyexp}. For the lower bound, one step changes the index
by at most $1$, so $u\mathrel{R^k}v$ implies $|u-v|\le k$; take $u=0$, $v=N-1$.
\end{proof}

\section{Recurrence as a greatest fixed point}

\begin{definition}
For a frame $F$ define $\Dia_F X=\{w:\exists v\,(w\mathrel{R}v\wedge v\in X)\}$; this is
monotone and is the semantic diamond. A set $X$ is \emph{post-fixed} if
$X\subseteq\Dia_F X$, and $\gfp(\Dia_F)$ is the union of all post-fixed sets.
\end{definition}

\begin{proposition}
$\gfp(\Dia_F)$ is post-fixed, contains every post-fixed set, and satisfies
$\Dia_F(\gfp(\Dia_F))=\gfp(\Dia_F)$.
\end{proposition}

\begin{proof}[Proof sketch]
Post-fixedness and maximality are immediate. For the fixed-point equation, $\subseteq$ is
post-fixedness applied once; for $\supseteq$, if $w\in\Dia_F(\gfp)$ then $\gfp\cup\{w\}$ is
post-fixed, hence contained in $\gfp$.
\end{proof}

\begin{definition}
$w$ is \emph{recurrent} if $w\mathrel{R^m}w$ for some $m>0$, and \emph{reaches recurrence} if
some recurrent world is $R^k$-accessible from it. By Theorem~\ref{thm:spec}, recurrence of
$w$ is exactly $n$-soundness of $w$ for some $n>0$.
\end{definition}

\begin{theorem}[Identification]\label{thm:gfp}
On a finite frame, $\gfp(\Dia_F)=\{w : w \text{ reaches recurrence}\}$.
\end{theorem}

\begin{proof}[Proof sketch]
($\supseteq$) The set of worlds reaching recurrence is post-fixed: if $w$ reaches a recurrent
$z$, either $w=z$, and a positive-length cycle at $z$ supplies a successor still reaching
$z$; or the first step towards $z$ lands on a world still reaching $z$. Maximality finishes.
($\subseteq$) Let $X$ be post-fixed and $w\in X$; choose for each $x\in X$ a successor
$c(x)\in X$. The orbit $w,c(w),c^2(w),\dots$ stays in $X$ and repeats: $c^i(w)=c^j(w)$ with
$i<j$. Then $c^i(w)$ is recurrent with cycle length $j-i>0$ and is reachable from $w$.
\end{proof}

\begin{corollary}
If $F$ is serial then $\gfp(\Dia_F)=W$; hence on the support frame of a finite row-stochastic
chain every state reaches recurrence: for each $u$ there are $z$, $k\ge0$ and $m>0$ with
$P^k(u,z)>0$ and $P^m(z,z)>0$. This strengthens Theorem~\ref{thm:pigeon} from ``some state''
to ``from every state''.
\end{corollary}

\begin{example}[The naive conjecture fails]\label{ex:absorb}
Let $D$ be the two-state chain moving to state $1$ from either state with probability $1$.
State $1$ has a self-loop and is recurrent; state $0$ is transient, since every
positive-length path from $0$ ends at $1\ne0$. Yet $\{0,1\}$ is post-fixed, so
$0\in\gfp(\Dia_D)$. Hence the greatest fixed point of the diamond is in general strictly
larger than the recurrent set.
\end{example}

\begin{remark}
The failure is an expressiveness limitation: the diamond looks only forward, so a fixed point
of a monotone operator on sets can detect survival but not return. Isolating the recurrent
set requires the genuinely cyclic predicate $w\mathrel{R^m}w$.
\end{remark}

\section{Aggregation: lumpability is a bounded morphism}

\begin{definition}[Strong lumpability]
For finite $S$, a map $f:S\to T$ \emph{lumps} $P$ onto $Q$ if for all $u\in S$, $y\in T$,
\[
\sum_{v\,:\,f(v)=y} P(u,v) \;=\; Q\bigl(f(u),y\bigr).
\]
\end{definition}

\begin{definition}[Bounded morphism]
$f:W_F\to W_G$ is a \emph{bounded morphism} when (forth) $u\mathrel{R_F}v$ implies
$f(u)\mathrel{R_G}f(v)$, and (back) $f(u)\mathrel{R_G}y$ implies $u\mathrel{R_F}v$ for some
$v$ with $f(v)=y$.
\end{definition}

\begin{theorem}\label{thm:lump}
If $P$ has nonnegative entries and $f$ lumps $P$ onto $Q$, then $f$ is a bounded morphism
$\supp(P)\to\supp(Q)$.
\end{theorem}

\begin{proof}
Forth: the single positive term $P(u,v)$ bounds below the block sum over $f^{-1}(f(v))$,
which equals $Q(f(u),f(v))$. Back: if $Q(f(u),y)>0$ then the block sum over $f^{-1}(y)$ is
positive, and a positive sum of nonnegative reals has a positive summand.
\end{proof}

\begin{remark}
Row-stochasticity is not used: only nonnegativity. The modal content of aggregation is
independent of mass conservation.
\end{remark}

\begin{corollary}[Validity transfer]\label{cor:transfer}
If $f$ lumps $P$ onto $Q$ surjectively then every formula valid on $\supp(P)$ is valid on
$\supp(Q)$; hence $T_P\subseteq T_Q$. Moreover a surjective lumping of a lazy chain is lazy,
so self-soundness is a lumping invariant.
\end{corollary}

\begin{example}
For $m\mid n$, reduction $\ZZ/n\to\ZZ/m$ lumps $C_n$ onto $C_m$, so
$T_{C_n}\subseteq T_{C_m}$: the modal theories of cycles are monotone in divisibility,
mirroring $n\NN\subseteq m\NN$.
\end{example}

\begin{theorem}[Non-laziness is not modally definable]
No set $\Gamma$ of modal formulas defines the class of frames in which no world has a
self-loop.
\end{theorem}

\begin{proof}
Suppose it did. The $2$-cycle $C_2$ has no self-loops, so all of $\Gamma$ is valid on it.
Reduction $\ZZ/2\to\ZZ/1$ is a surjective lumping, so by Corollary~\ref{cor:transfer} all of
$\Gamma$ is valid on $C_1$; but $C_1$ is the one-state lazy chain, whose state has a
self-loop.
\end{proof}

\section{Algorithms}

\begin{enumerate}
\item[(A)] \textbf{Support-power test.} Replace each entry by $[P(u,v)>0]$ and compute the
$n$-th Boolean matrix power by repeated squaring, in $O(N^3\log n)$ operations. Correctness is
Theorem~\ref{thm:supp}; this avoids floating-point underflow for large $n$.
\item[(B)] \textbf{Cycle-monoid conductor.} Enumerate return lengths up to a cutoff, take
their $\gcd$ $g$: if $g>1$ the state is periodic with period $g$; if $g=1$ the spectrum is
cofinite by Theorem~\ref{thm:cofinite} and the conductor is found by a linear sieve over the
monoid generated by the observed lengths.
\item[(C)] \textbf{Primitivity exponent.} Decide primitivity by irreducibility plus the
$\gcd$ test (Theorem~\ref{thm:primap}); find the exponent by incrementing $n$ and testing the
Boolean power, with termination guaranteed by the bounds of Section~7.
\item[(D)] \textbf{Greatest fixed point.} Iterate $X_0=W$, $X_{k+1}=\Dia X_k$; the sequence
decreases and stabilises in at most $N$ steps at $\gfp(\Dia)$, which by Theorem~\ref{thm:gfp}
is the set of states reaching recurrence.
\item[(E)] \textbf{Lumpability check.} Verify the block-sum identity in $O(N^2)$ additions per
block pair; if it passes, Corollary~\ref{cor:transfer} guarantees persistence of all modal
validities.
\end{enumerate}

\section{Discussion}

\subsection{What probability contributes to logic}
Exactly one thing: seriality. Every impossibility result above factors through the lemma that
a probability distribution cannot vanish identically; row-stochasticity is used nowhere else.
The G\"odelian discipline, whose content is that every chain of justification terminates, is
unavailable to any system that conserves mass.

\subsection{What logic contributes to probability}
First, a conceptual relocation of mixing: ``does the chain mix?'' becomes ``is a numerical
semigroup cofinite?'', answered completely by Theorem~\ref{thm:cofinite}; the usual
hypotheses (a self-loop, laziness, coprime cycles) are strictly weaker special cases, as
Example~\ref{ex:ap} shows. Second, limitative results with small witnesses, since aggregation
is a bounded morphism. Third, a diagnosis of expressiveness: Theorem~\ref{thm:gfp} with
Example~\ref{ex:absorb} pins down what a forward-looking modal fixed point sees about long-run
behaviour --- survival, but not return.

\subsection{Scope and limitations}
The dictionary is about supports, so it cannot see rates: mixing time, spectral gaps and the
Perron eigenvalue lie outside it. Only \emph{strong} lumpability corresponds to a bounded
morphism; weak lumpability, depending on the initial distribution, does not. Several
statements presuppose a nonempty stock of propositional variables.

\section{Future directions}

\begin{enumerate}
\item \textbf{Quantitative refinement.} Is a Wielandt-type bound $N^2-2N+2$ recoverable purely
by path excision?
\item \textbf{Weighted supports.} Replace ``positive'' by ``at least $\varepsilon$'' and ask
which parts of the dictionary survive, connecting combinatorial exponents to mixing times.
\item \textbf{Reducible chains.} A general chain decomposes into transient states and terminal
classes; Theorem~\ref{thm:gfp} suggests a relativised fixed point per class.
\item \textbf{Cyclic operators.} Which extension of the modal language defines the recurrent
set, and what is its definability theory?
\item \textbf{Continuous time and general state spaces.} Do the support-power theorem and the
aperiodicity criterion have kernel analogues, with $\gcd$ replaced by a group of periods?
\item \textbf{Lumpability lattice.} Characterise which modal theories arise from chains, i.e.\
a completeness theorem for the probabilistic semantics.
\end{enumerate}

\section{Conclusion}

Passing from a stochastic matrix to the relation ``this transition is possible'' turns a piece
of analysis into a piece of combinatorics without losing anything about possibility. On the
resulting frames, the logic of provability is impossible and the logic of self-declared
soundness is forced; the set of degrees at which a state trusts itself is a numerical
semigroup whose cofiniteness --- equivalently, the chain's primitivity --- is governed by the
single condition that no integer $d\ge2$ divides all return lengths; the thresholds are
explicit and, for the nearest-neighbour chain, exactly $N-1$; state aggregation is a
structure-preserving map whose limitations are the classical failures of modal definability;
and the greatest fixed point of possibility computes not recurrence but the ability to reach
it.

